import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM kernel using CUTE tensors for global memory addressing
// Block computes a BM x BN tile of C, with BK reduction step per iteration.
// Each thread computes a TM x TN sub-tile stored in registers.
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int TM = 8;
constexpr int TN = 8;
// blockDim = (BN/TN, BM/TM) = (16, 16) -> 256 threads

__device__ __forceinline__ float4 load_A4_dev(const float* __restrict__ A, int M, int K, int gr, int gc) {
    float4 val;
    if (gr < M && gc + 3 < K) {
        val = *reinterpret_cast<const float4*>(&A[gr * K + gc]);
    } else {
        val.x = (gr < M && gc + 0 < K) ? A[gr * K + gc + 0] : 0.f;
        val.y = (gr < M && gc + 1 < K) ? A[gr * K + gc + 1] : 0.f;
        val.z = (gr < M && gc + 2 < K) ? A[gr * K + gc + 2] : 0.f;
        val.w = (gr < M && gc + 3 < K) ? A[gr * K + gc + 3] : 0.f;
    }
    return val;
}
__device__ __forceinline__ float4 load_B4_dev(const float* __restrict__ B, int K, int N, int gr, int gc) {
    float4 val;
    if (gr < K && gc + 3 < N) {
        val = *reinterpret_cast<const float4*>(&B[gr * N + gc]);
    } else {
        val.x = (gr < K && gc + 0 < N) ? B[gr * N + gc + 0] : 0.f;
        val.y = (gr < K && gc + 1 < N) ? B[gr * N + gc + 1] : 0.f;
        val.z = (gr < K && gc + 2 < N) ? B[gr * N + gc + 2] : 0.f;
        val.w = (gr < K && gc + 3 < N) ? B[gr * N + gc + 3] : 0.f;
    }
    return val;
}
__global__ void cute_gemm_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
    __shared__ float sA[2][BM][BK];
    __shared__ float sB[2][BK][BN];
    // CUTE tensor describing the global output matrix (row-major)
    Tensor gC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));
    int tx = threadIdx.x; // 0..15 -> N sub-tile
    int ty = threadIdx.y; // 0..15 -> M sub-tile
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int row0 = by * BM;
    int col0 = bx * BN;
    int tid = ty * (BN / TN) + tx; // 0..255
    const int NTHREADS = (BM / TM) * (BN / TN); // 256
    (void)NTHREADS;
    // Each thread loads exactly one float4 for A tile and one float4 for B tile per K-slab
    int rA = tid / (BK / 4);
    int cA4 = tid % (BK / 4);
    int cA = cA4 * 4;
    int gr_a = row0 + rA;
    int rB = tid / (BN / 4);
    int cB4 = tid % (BN / 4);
    int cB = cB4 * 4;
    int gc_b = col0 + cB;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.f;
        }
    }
    int cur = 0;
    // Prime the pipeline: load first K-slab into buffer 0
    {
        float4 a0 = load_A4_dev(A, M, K, gr_a, 0 + cA);
        float4 b0 = load_B4_dev(B, K, N, 0 + rB, gc_b);
        sA[0][rA][cA + 0] = a0.x;
        sA[0][rA][cA + 1] = a0.y;
        sA[0][rA][cA + 2] = a0.z;
        sA[0][rA][cA + 3] = a0.w;
        sB[0][rB][cB + 0] = b0.x;
        sB[0][rB][cB + 1] = b0.y;
        sB[0][rB][cB + 2] = b0.z;
        sB[0][rB][cB + 3] = b0.w;
    }
    __syncthreads();
    for (int k0 = 0; k0 < K; k0 += BK) {
        int nxt = cur ^ 1;
        bool has_next = (k0 + BK < K);
        float4 a_next, b_next;
        if (has_next) {
            a_next = load_A4_dev(A, M, K, gr_a, k0 + BK + cA);
            b_next = load_B4_dev(B, K, N, k0 + BK + rB, gc_b);
        }
        // Compute: register-blocked outer product over the BK reduction dim
        // (overlapped with the prefetch loads issued above)
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_reg[TM];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_reg[i] = sA[cur][ty * TM + i][kk];
            }
            float b_reg[TN];
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_reg[j] = sB[cur][kk][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        if (has_next) {
            sA[nxt][rA][cA + 0] = a_next.x;
            sA[nxt][rA][cA + 1] = a_next.y;
            sA[nxt][rA][cA + 2] = a_next.z;
            sA[nxt][rA][cA + 3] = a_next.w;
            sB[nxt][rB][cB + 0] = b_next.x;
            sB[nxt][rB][cB + 1] = b_next.y;
            sB[nxt][rB][cB + 2] = b_next.z;
            sB[nxt][rB][cB + 3] = b_next.w;
        }
        __syncthreads();
        cur = nxt;
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int gr = row0 + ty * TM + i;
        if (gr >= M) continue;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int gc = col0 + tx * TN + j;
            if (gc < N) {
                gC(gr, gc) = acc[i][j];
            }
        }
    }
}

torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");

    auto A_c = A.contiguous().to(torch::kFloat32);
    auto B_c = B.contiguous().to(torch::kFloat32);

    int M = (int)A_c.size(0);
    int K = (int)A_c.size(1);
    int N = (int)B_c.size(1);
    TORCH_CHECK((int)B_c.size(0) == K, "B.size(0) must equal A.size(1)");

    auto C = torch::empty({M, N}, A_c.options());

    dim3 block(BN / TN, BM / TM); // (16, 16)
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_gemm_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE gemm launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_gemm_tiled_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemm(A, B)

